// Normalizar payload entrante desde Webhook o lectura de live-status
const input = $input.first() ? $input.first().json : {};
const query = input.query || {};
const body = input.body || {};

const episode = Number(body.episode || query.episode || 4);
const season = Number(body.season || query.season || 1);
const title = body.title || query.title || 'IA Estrecha (ANI) vs. IA General (AGI)';
const concept = body.concept || query.concept || 'Diferencia entre algoritmos especializados de hoy y la hipotética inteligencia humana artificial';
const audioFilename = body.audio || query.audio || 'Temporada_1_Episodio_4_IA_Estrecha_ANI_vs_IA_General_AGI.mp3';
const audioBytes = Number(body.bytes || query.bytes || 11254849);
const duration = body.duration || query.duration || '05:51';
const ytVideoUrl = body.yt_video || query.yt_video || 'https://www.youtube.com/@jose.iasinfiltro';
const ytShortUrl = body.yt_short || query.yt_short || 'https://ia-sin-filtro.duckdns.org/episodes/shorts_ep4_youtube.mp4';

return [{
  json: {
    season,
    episode,
    title,
    concept,
    audioFilename,
    audioBytes,
    duration,
    ytVideoUrl,
    ytShortUrl,
    tweetText: `🎙️ ¡Estrenamos nuevo episodio de #IASinFiltro!\n\nEpisodio ${episode}: "${title}"\n\n¿Por qué el algoritmo de Spotify no puede prepararte la cena? Desarmamos el mito de la AGI frente a la IA especializada de hoy.\n\n🎧 Escúchalo en Spotify, Apple, iVoox y YouTube:\n👉 https://mgjosea.github.io/ia-sin-filtro-podcast/`
  }
}];
